class Plan(BaseModel):
    steps: list[str] = Field(description="Ordered, concrete sub-tasks")

def make_plan(objective: str) -> Plan:
    planner = get_model().with_structured_output(Plan)
    return planner.invoke([
        SystemMessage(content="Break the objective into 2-5 concrete, "
                              "ordered steps a support agent can execute."),
        HumanMessage(content=objective)])

def plan_approval_gate(plan: Plan, *, auto_approve_threshold=5) -> dict:
    flagged = [s for s in plan.steps if any(kw in s.lower()
               for kw in ("refund", "delete", "override", "fraud"))]
    too_long = len(plan.steps) > auto_approve_threshold
    requires_human = bool(flagged) or too_long
    return {"approved": not requires_human,
            "requires_human": requires_human, "flagged_steps": flagged}

def plan_node(state: dict) -> dict:
    plan = make_plan(state["objective"])
    gate = plan_approval_gate(plan)
    log_plan(state["objective"], plan, gate)  # AUDIT: before ANY step
    return {"plan": plan.steps, "remaining": list(plan.steps), "plan_gate": gate}

MAX_REFLECTIONS = 2                    # bound the loop (Module 1)
CRITERIA = ("1) refund amount within stated eligibility; "
            "2) reply in the customer's language; "
            "3) cites the applicable Tawseel policy; "
            "4) no PII beyond what the customer supplied.")
class Critique(BaseModel):
    passes: bool
    issues: list[str]

def reflect(candidate: str, context: str) -> Critique:
    critic = get_model().with_structured_output(Critique)
    return critic.invoke([
        SystemMessage(content=f"Critique the draft against: {CRITERIA}"),
        HumanMessage(content=f"Context:\n{context}\n\nDraft:\n{candidate}")])

def reflect_and_revise(draft: str, context: str) -> dict:
    for i in range(MAX_REFLECTIONS):
        c = reflect(draft, context)
        if c.passes:
            return {"draft": draft, "passes_used": i + 1, "final_passed": True}
        draft = get_model().invoke([SystemMessage(
            content="Revise the draft to fix EXACTLY these issues."),
            HumanMessage(content=f"Issues: {c.issues}\n\nDraft:\n{draft}")]).content
    return {"draft": draft, "passes_used": MAX_REFLECTIONS, "final_passed": False}
